def f(I):
    import numpy as np, collections
    A=np.array(I)
    vals,cnt=collections.Counter(A.flatten().tolist()).most_common()
    bg,area=vals[0]
    # bars: maximal straight segments (len>=2) of a single color !=bg
    cells=[(r,c,int(v)) for r in range(A.shape[0]) for c in range(A.shape[1]) for v in [A[r,c]] if v!=bg]
    # group by color, find straight maximal runs
    from itertools import groupby
    bar_cells=[]
    for c in range(A.shape[1]):
        seq=[int(A[r][c]) for r in range(A.shape[0])]
        segs=[]
        cur=[]
        for r,v in enumerate(seq):
            if cur and cur[-1]==v: cur.append((r,c))
            elif cur: segs.append(cur); cur=[]
            else: cur=[(r,c)]
        if cur: segs.append(cur)
        for s in segs:
            if len(set(r for r,_ in s))<=1 and len(s)>=2 and int(A[s[0][0]][s[0][1]])!=bg:
                bar_cells.append(s)
    # similarly rows
    for r in range(A.shape[0]):
        seq=[int(A[r][c]) for c in range(A.shape[1])]
        segs=[]; cur=[]
        for c,v in enumerate(seq):
            if cur and cur[-1]==v: cur.append((r,c))
            elif cur: segs.append(cur); cur=[]
            else: cur=[(r,c)]
        if cur: segs.append(cur)
        for s in segs:
            if len({x for x,_ in s})==1 and len(s)>=2:
                bar_cells.append(s)
    bars=[s for s in bar_cells if int(A[s[0][0]][s[0][1]])!=bg]
    mark=set()
    for r in range(A.shape[0]):
        for c in range(A.shape[1]):
            v=int(A[r][c])
            if v!=bg and v!=int(A[bars[0][0][0]][bars[0][0][1]]) if bars else False:
                mark.add((r,c))
    if not bars:
        return [[int(x) for x in A.flatten()] ] 
    barcolor=int(A[bars[0][0][0]][bars[0][0][1]])
    # classify bars: horizontal if len(unique rows)==1 else vertical
    horiz=[b for b in bars if len({r for r,_ in b})==1]
    vert=[b for b in bars if len({r for r,_ in b})==1]
    rays=[]
    for b in bars:
        base=(b[0]) if vert else (b[0],0)
        start,bend = base[0], base[1]
        if vert:
            for k in range(1,len(b),2):
                sc = bend+k
                if sc<A.shape[1]:
                    cr,cj=b[0]
                    d=(0,-1) if sc>start else (0,1)
                    rr=cr; cc=sc
                    while True:
                        if (rr,cc) in mark: mark.discard((rr,cc))
                        if A[rr,cc]==barcolor: break
                        A[rr,cc]=4
                        if (rr+d[0],cc+d[1]) not in [(x,y) for x,_ in b] and abs(rr+b[0][0])>0 and True:
                            pass
                        rr+=d[0]; cc+=d[1]
                        if rr<0 or rr>=A.shape[0] or cc<0 or cc>=A.shape[1] or (rr,cc) in [(x,y) for y in range(A.shape[1]) for x in [sc-k+0]]: break
        else:
            for k in range(1,len(b),2):
                sc = start+k
                sr,beg=(b[0])[0]
                d=(1,0) if sc<sr else (-1,0)
                rr=sr; cc=beg
                # walk
                pass
    # rewrite cleaner in next cell
    return A.tolist()
